mapper.insert:
insert into ingestion_task_item (
    id, task_id, current_execution_id, kb_id, asset_id, file_name, file_hash, source_url,
    stage, status, progress, dedupe_strategy, dedupe_result, duplicate_asset_id,
    error_code, error_message, created_at, updated_at, finished_at
) values (
    #{id}, #{taskId}, #{currentExecutionId}, #{kbId}, #{assetId}, #{fileName}, #{fileHash}, #{sourceUrl},
    #{stage}, #{status}, #{progress}, #{dedupeStrategy}, #{dedupeResult}, #{duplicateAssetId},
    #{errorCode}, #{errorMessage}, #{createdAt}, #{updatedAt}, #{finishedAt}
)

insert into ingestion_item_parse_attempt (
    item_id, attempt_no, status, request_id, job_id, source_revision,
    request_snapshot, created_at, updated_at, finished_at
) values (
    #{itemId}, #{attemptNo}, #{status}, #{requestId}, #{jobId}, #{sourceRevision},
    cast(#{requestSnapshot} as json), #{createdAt}, #{updatedAt}, #{finishedAt}
)

insert into ingestion_item_artifact (
    execution_id, artifact_type, artifact_version, provenance,
    producer_claim_version, object_key, content_sha256, created_at
) values (
    #{executionId}, #{artifactType}, #{artifactVersion}, #{provenance},
    #{producerClaimVersion}, #{objectKey}, #{contentSha256}, #{createdAt}
)
on duplicate key update execution_id = execution_id

mapper.update:
update ingestion_task_item
set current_execution_id = #{executionId},
    updated_at = #{updatedAt}
where id = #{itemId}
  and current_execution_id is null

