select 
from ingestion_task
where id = #{taskId}
  and kb_id = #{kbId}

select 
from ingestion_task
where created_by = #{createdBy}
  and client_request_id = #{clientRequestId}
limit 1

select 
from ingestion_task
where kb_id = #{kbId}

    and status = #{status}

order by created_at desc, id desc
limit #{limit}

select 
from ingestion_task_item iti
inner join ingestion_task it on it.id = iti.task_id
where it.kb_id = #{kbId}
  and it.id = #{taskId}
  and iti.id = #{itemId}

mapper.update:
update ingestion_item_execution ie
inner join ingestion_task_item iti
    on iti.current_execution_id = ie.id
   and iti.id = ie.item_id
set ie.lease_until = timestampadd(second, #{leaseSeconds}, current_timestamp(6)),
    ie.updated_at = current_timestamp(6)
where iti.id = #{itemId}
  and ie.execution_epoch = #{executionEpoch}
  and ie.phase = #{expectedExecutionStage}
  and ie.claim_version = #{claimVersion}
  and ie.lease_token = #{leaseToken}
  and ie.lease_until > current_timestamp(6)
  and ie.execution_status = 'ACTIVE'
  and iti.status = 'RUNNING'

update ingestion_item_execution ie
inner join ingestion_task_item iti
    on iti.current_execution_id = ie.id
   and iti.id = ie.item_id
inner join ingestion_task it on it.id = iti.task_id
set ie.phase = case
        when #{nextExecutionStage} in ('COMPLETE', 'FAILED') then ie.phase
        else #{nextExecutionStage}
    end,
    ie.execution_status = case
        when #{nextExecutionStage} = 'COMPLETE' then 'SUCCEEDED'
        when #{nextExecutionStage} = 'FAILED' then 'FAILED'
        else 'ACTIVE'
    end,
    ie.phase_retry_count = #{nextStageRetryCount},
    ie.phase_started_at = case
        when #{nextExecutionStage} in ('COMPLETE', 'FAILED') then ie.phase_started_at
        else #{nextStageStartedAt}
    end,
    ie.next_action_at = #{nextActionAt},
    ie.error_code = #{errorCode},
    ie.error_message = #{errorMessage},
    ie.lease_token = null,
    ie.lease_until = null,
    ie.updated_at = coalesce(#{updatedAt}, current_timestamp(6)),
    ie.finished_at = #{finishedAt}
where iti.id = #{itemId}
  and iti.task_id = #{taskId}
  and it.kb_id = #{kbId}
  and ie.execution_epoch = #{executionEpoch}
  and ie.phase = #{expectedExecutionStage}
  and ie.claim_version = #{expectedClaimVersion}
  and ie.lease_token = #{leaseToken}
  and ie.execution_status = 'ACTIVE'
  and iti.status = 'RUNNING'

