       producer_claim_version, object_key, content_sha256, created_at
from ingestion_item_artifact
where execution_id = #{executionId}
  and artifact_type = #{artifactType}

select ie.id
from ingestion_task_item iti
inner join ingestion_item_execution ie
    on ie.id = iti.current_execution_id
   and ie.item_id = iti.id
where iti.id = #{itemId}
  and ie.execution_epoch = #{executionEpoch}
  and ie.phase = #{expectedExecutionStage}
  and ie.claim_version = #{claimVersion}
  and ie.lease_token = #{leaseToken}
  and ie.execution_status = 'ACTIVE'
  and iti.status = 'RUNNING'
for update

