update ingestion_task_item iti inner join ingestion_task it on it.id = iti.task_id set iti.current_execution_id = #{nextExecutionId}, iti.stage = #{projection.stage}, iti.status = #{projection.status}, iti.progress = #{projection.progress}, iti.error_code = null, iti.error_message = null, iti.updated_at = #{updatedAt}, iti.finished_at = null where it.kb_id = #{kbId} and it.id = #{taskId} and iti.id = #{itemId} and iti.status = 'FAILED'
and iti.current_execution_id is null
and iti.current_execution_id = #{expectedCurrentExecutionId}
